mapper.select:
select 
from alert_event_handler_audit a
where a.id = #{value}

select from alert_event_handler_audit a where a.parent_id in
#{parentId}
order by a.parent_id, a.id

sql.where:
a.parent_id is null

    and a.id = #{rootAuditId}


    and a.alert_id = #{alertId}


    and (
        a.unique_key like concat('%', #{keyword}, '%')
        or a.handler_name like concat('%', #{keyword}, '%')
        or a.handler like concat('%', #{keyword}, '%')
        or exists (
            select 1
            from alert keyword_alert
            where keyword_alert.id = a.alert_id
              and keyword_alert.title like concat('%', #{keyword}, '%')
        )
    )


    and a.event = #{event}


    and a.handler = #{handler}


    and a.status = #{status}


    and a.start_time >= STR_TO_DATE(#{timeRange[0]}, '%Y-%m-%d %H:%i')


    and a.start_time <= STR_TO_DATE(#{timeRange[1]}, '%Y-%m-%d %H:%i')


    and exists (
        select 1
        from alert_event_handler_audit child_audit
        where child_audit.parent_id = a.id
    )


    and not exists (
        select 1
        from alert_event_handler_audit child_audit
        where child_audit.parent_id = a.id
    )
